<?php require '../config.php';require_admin();$adminPage=true;$pageTitle='Quản trị';$counts=[];foreach(['products'=>'Sản phẩm','categories'=>'Danh mục','users'=>'Tài khoản','orders'=>'Đơn hàng','contacts'=>'Liên hệ'] as $t=>$label)$counts[$label]=(int)$pdo->query("SELECT COUNT(*) FROM `$t`")->fetchColumn();require '../includes/header.php';?><div class="row g-4"><div class="col-md-3"><?php require 'nav.php';?></div><div class="col-md-9"><h1 class="section-title">Bảng điều khiển</h1><p>Xin chào quản trị viên. Chọn mục bên trái để quản lý dữ liệu.</p><div class="row g-3"><?php foreach($counts as $label=>$num): ?><div class="col-sm-6 col-xl-4"><div class="content-card"><div class="small-muted"><?= e($label) ?></div><div class="display-5 fw-bold text-red"><?= $num ?></div></div></div><?php endforeach; ?></div></div></div><?php require '../includes/footer.php';?>
